SELECT ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='merchant_presentation' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_unicode_ci')=1 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='merchant_presentation')=6 AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='merchant_presentation' AND CONSTRAINT_NAME IN ('PRIMARY','fk_presentation_merchant','ck_presentation_merchant','ck_presentation_keywords','ck_presentation_logo'))=5) AS satisfied
